154: pub fn run_sync(r: &Registry, job: &JobKind) -> FsResult<(Vec<Location>, Vec<Location>)> {
155:     let cancel = Arc::new(AtomicBool::new(false));
156:     let ctx = JobCtx { id: 0, cancel, emit: Box::new(|_| {}) };
