169: fn run_inner(r: &Registry, job: &JobKind, ctx: &JobCtx) -> FsResult<(Vec<Location>, Vec<Location>)> {
170:     let mut created = vec![];
171:     let mut touched = vec![];
172:     match job {
173:         JobKind::Copy { srcs, dest } | JobKind::Move { srcs, dest } => {
174:             let moving = matches!(job, JobKind::Move { .. });
175:             let total: u64 = srcs.iter().map(|s| measure(r, s)).sum::<u64>().max(1);
176:             let mut p = Progress { ctx, done: 0, total, last: 0 };
177:             let dv = vfs(r, dest)?;
178:             touched.push(dest.clone());
179:             for s in srcs {
180:                 let name = unique_name(dv.as_ref(), dest, &s.name(), None);
181:                 let target = dest.join(&name);
182:                 if moving && s.fs == dest.fs {
183:                     if s.parent().as_ref() == Some(dest) {
184:                         continue;
185:                     }
186:                     if dest.starts_with(s) {
187:                         return Err(FsError::Other("cannot move a folder into itself".into()));
188:                     }
189:                     match dv.rename(&s.path, &target.path) {
190:                         Ok(()) => {
191:                             p.bump(measure(r, &target), &name);
192:                             created.push(target);
193:                             touched.extend(s.parent());
194:                             continue;
195:                         }
196:                         Err(FsError::Cancelled) => return Err(FsError::Cancelled),
197:                         Err(_) => {} // cross-device: fall through to copy + delete
198:                     }
199:                 }
200:                 copy_tree(r, s, &target, &mut p)?;
201:                 created.push(target);
202:                 if moving {
203:                     vfs(r, s)?.remove(&s.path, false)?;
204:                     touched.extend(s.parent());
205:                 }
206:             }
207:         }
208:         JobKind::Duplicate { srcs } => {
209:             let total: u64 = srcs.iter().map(|s| measure(r, s)).sum::<u64>().max(1);
210:             let mut p = Progress { ctx, done: 0, total, last: 0 };
211:             for s in srcs {
212:                 let Some(dir) = s.parent() else { continue };
213:                 let v = vfs(r, s)?;
214:                 let name = unique_name(v.as_ref(), &dir, &s.name(), Some("copy"));
215:                 let target = dir.join(&name);
216:                 copy_tree(r, s, &target, &mut p)?;
217:                 created.push(target);
218:                 touched.push(dir);
219:             }
220:         }
221:         JobKind::Trash { srcs } | JobKind::Delete { srcs } => {
222:             let trash = matches!(job, JobKind::Trash { .. });
223:             for (i, s) in srcs.iter().enumerate() {
224:                 if ctx.cancel.load(Ordering::Relaxed) {
225:                     return Err(FsError::Cancelled);
226:                 }
227:                 let v = vfs(r, s)?;
228:                 v.remove(&s.path, trash && v.supports_trash())?;
229:                 touched.extend(s.parent());
230:                 (ctx.emit)(JobEvent::Progress { id: ctx.id, done: i as u64 + 1, total: srcs.len() as u64, current: s.name() });
231:             }
232:         }
233:     }
234:     touched.sort();
235:     touched.dedup();
236:     Ok((created, touched))
237: }

