168:         return PasswordCheck::Ok(entries);
169:     }
170:     match extract_to_mem(data, &first.name, Some(password)) {
171:         Ok(_) => PasswordCheck::Ok(entries),
172:         Err(ZipError::BadPassword) => PasswordCheck::Wrong,
173:         Err(_) => PasswordCheck::Wrong,
174:     }
175: }
