250: /// Extract every entry into `dest` (creating folders). Returns (files, bytes).
251: pub fn extract(reg: &Registry, src: &Location, dest: &Location, password: Option<&str>, mut progress: impl FnMut(&str, u64, u64)) -> R<(usize, u64)> {
252:     let sv = reg.get(&src.fs).ok_or_else(|| ZipError::Io("missing file system".into()))?;
253:     let dv = reg.get(&dest.fs).ok_or_else(|| ZipError::Io("missing file system".into()))?;
254:     let bytes = read_archive(sv.as_ref(), src)?;
255:     let entries = list(&bytes, password)?;
256:     let total: u64 = entries.iter().filter(|e| !e.is_dir).map(|e| e.size).sum();
257:     let mut done = 0u64;
258:     let mut files = 0usize;
259:     for e in &entries {
260:         let Some(target) = safe_join(dest, &e.name) else { continue };
261:         if e.is_dir {
262:             let _ = dv.mkdir(&target.path);
263:             continue;
264:         }
265:         let data = decode(&bytes, &e.name, password)?;
266:         if let Some(parent) = e.name.rsplit_once('/').map(|(p, _)| p) {
267:             let mut cur = dest.clone();
268:             for seg in parent.split('/').filter(|s| !s.is_empty()) {
269:                 cur = cur.join(seg);
270:                 let _ = dv.mkdir(&cur.path);
271:             }
272:         }
273:         dv.write(&target.path, &data).map_err(|x| ZipError::Io(x.to_string()))?;
274:         done += e.size;
275:         files += 1;
276:         progress(&e.name, done, total.max(1));
277:     }
278:     Ok((files, done))
279: }
