289: fn dos_time(ts: i64) -> (u16, u16) {
290:     use chrono::{Datelike, Timelike};
291:     let d = { use chrono::TimeZone; chrono::Local.timestamp_opt(ts, 0).single().unwrap_or_else(chrono::Local::now) };
292:     let time = ((d.hour() as u16) << 11) | ((d.minute() as u16) << 5) | (d.second() as u16 / 2);
293:     let date = (((d.year() - 1980).max(0) as u16) << 9) | ((d.month() as u16) << 5) | d.day() as u16;
294:     (time, date)
295: }
296: impl Out<'_> {
297:     fn file(&mut self, reg: &Registry, src: &Location, name: &str) -> R<()> {
298:         let v = reg.get(&src.fs).ok_or_else(|| ZipError::Io("missing file system".into()))?;
299:         let st = v.stat(&src.path).map_err(|e| ZipError::Io(e.to_string()))?;
300:         let data = v.read(&src.path, 1 << 31).map_err(|e| ZipError::Io(e.to_string()))?;
301:         let crc = crc32(&data);
302:         let comp = if data.len() > 64 { miniz_oxide::deflate::compress_to_vec(&data, self.level) } else { data.clone() };
303:         let (method, mut payload) = if comp.len() < data.len() { (8u16, comp) } else { (0u16, data.clone()) };
304:         let (time, date) = dos_time(st.modified.unwrap_or_else(crate::model::now_secs));
305:         let mut flags = 0x0800u16; // UTF-8 names
306:         if self.password.is_some() {
307:             flags |= 1;
308:             let mut header = [0u8; 12];
309:             let mut seed = (crate::model::now_secs() as u64) ^ (crc as u64) ^ 0x9E37_79B9_7F4A_7C15;
310:             for b in header.iter_mut() {
311:                 seed ^= seed << 13;
312:                 seed ^= seed >> 7;
313:                 seed ^= seed << 17;
314:                 *b = (seed & 0xFF) as u8;
315:             }
316:             header[11] = (crc >> 24) as u8;
317:             let mut c = Crypto::new(self.password.as_deref().unwrap_or(""));
318:             c.encrypt(&mut header);
319:             c.encrypt(&mut payload);
320:             let mut p = header.to_vec();
321:             p.extend(payload);
322:             payload = p;
323:         }
324:         let nb = name.as_bytes();
325:         let mut h = Vec::with_capacity(30 + nb.len());
326:         h.extend(0x04034b50u32.to_le_bytes());
327:         h.extend(20u16.to_le_bytes());
328:         h.extend(flags.to_le_bytes());
329:         h.extend(method.to_le_bytes());
330:         h.extend(time.to_le_bytes());
331:         h.extend(date.to_le_bytes());
332:         h.extend(crc.to_le_bytes());
333:         h.extend((payload.len() as u32).to_le_bytes());
334:         h.extend((data.len() as u32).to_le_bytes());
335:         h.extend((nb.len() as u16).to_le_bytes());
336:         h.extend(0u16.to_le_bytes());
337:         h.extend(nb);
338:         self.w.write_all(&h).map_err(|e| ZipError::Io(e.to_string()))?;
339:         self.w.write_all(&payload).map_err(|e| ZipError::Io(e.to_string()))?;
340:         let mut c = Vec::with_capacity(46 + nb.len());
341:         c.extend(0x02014b50u32.to_le_bytes());
342:         c.extend(20u16.to_le_bytes());
343:         c.extend(20u16.to_le_bytes());
344:         c.extend(flags.to_le_bytes());
345:         c.extend(method.to_le_bytes());
346:         c.extend(time.to_le_bytes());
347:         c.extend(date.to_le_bytes());
348:         c.extend(crc.to_le_bytes());
349:         c.extend((payload.len() as u32).to_le_bytes());
350:         c.extend((data.len() as u32).to_le_bytes());
351:         c.extend((nb.len() as u16).to_le_bytes());
352:         c.extend(0u16.to_le_bytes());
353:         c.extend(0u16.to_le_bytes());
354:         c.extend(0u16.to_le_bytes());
355:         c.extend(0u16.to_le_bytes());
356:         c.extend(0u32.to_le_bytes());
357:         c.extend((self.offset as u32).to_le_bytes());
358:         c.extend(nb);
359:         self.cd.extend(c);
360:         self.count = self.count.saturating_add(1);
361:         self.offset += (30 + nb.len() + payload.len()) as u64;
362:         Ok(())
363:     }
364:     fn finish(mut self) -> R<()> {
365:         let cd_off = self.offset;
366:         let cd = std::mem::take(&mut self.cd);
367:         self.w.write_all(&cd).map_err(|e| ZipError::Io(e.to_string()))?;
368:         let mut e = Vec::new();
369:         e.extend(0x06054b50u32.to_le_bytes());
370:         e.extend(0u16.to_le_bytes());
371:         e.extend(0u16.to_le_bytes());
372:         e.extend(self.count.to_le_bytes());
373:         e.extend(self.count.to_le_bytes());
374:         e.extend((cd.len() as u32).to_le_bytes());
375:         e.extend((cd_off as u32).to_le_bytes());
376:         e.extend(0u16.to_le_bytes());
377:         self.w.write_all(&e).map_err(|e| ZipError::Io(e.to_string()))?;
378:         self.w.flush().map_err(|e| ZipError::Io(e.to_string()))?;
379:         Ok(())
380:     }
381: }
