383: /// Compress files/folders (recursively) into a new `.zip`. Names keep their folder prefix.
384: pub fn compress(reg: &Registry, srcs: &[Location], dest_zip: &Location, password: Option<String>, level: u8, mut progress: impl FnMut(&str, u64, u64)) -> R<(usize, u64)> {
385:     let dv = reg.get(&dest_zip.fs).ok_or_else(|| ZipError::Io("missing file system".into()))?;
386:     let w = dv.create_write(&dest_zip.path).map_err(|e| ZipError::Io(e.to_string()))?;
387:     let mut out = Out { w, cd: Vec::new(), count: 0, offset: 0, password, level };
388:     let mut items: Vec<(Location, String)> = vec![];
389:     fn walk(reg: &Registry, l: &Location, name: String, out: &mut Vec<(Location, String)>) {
390:         let Some(v) = reg.get(&l.fs) else { return };
391:         if let Ok(e) = v.stat(&l.path) {
392:             if e.is_dir {
393:                 if let Ok(list) = v.list(&l.path) {
394:                     for c in list.into_iter().filter(|c| !c.symlink) {
395:                         walk(reg, &c.loc, format!("{}/{}", name, c.name), out);
396:                     }
397:                 }
398:             } else {
399:                 out.push((l.clone(), name));
400:             }
401:         }
402:     }
403:     for s in srcs {
404:         let Some(v) = reg.get(&s.fs) else { continue };
405:         let Ok(e) = v.stat(&s.path) else { continue };
406:         walk(reg, s, e.name.clone(), &mut items);
407:     }
408:     let total: u64 = items.len() as u64;
409:     let mut n = 0usize;
410:     for (l, name) in items {
411:         out.file(reg, &l, &name)?;
412:         n += 1;
413:         progress(&name, n as u64, total.max(1));
414:     }
415:     out.finish()?;
416:     Ok((n, total))
417: }
