329:     /// Extract on a worker thread with real progress; refreshes the viewer when finished.
330:     pub fn archive_extract(&self, src: &Location, dest: &Location, password: Option<String>) {
331:         let (reg, tx, src, dest, id) = (self.registry.clone(), self.tx.clone(), src.clone(), dest.clone(), self.id());
332:         let title = format!("Extracting {}", src.name());
333:         let _ = tx.send(Event::Job(JobEvent::Started { id, title: title.clone() }));
334:         spawn(move || {
335:             let tx2 = tx.clone();
336:             let r = crate::archive::extract(&reg, &src, &dest, password.as_deref(), |name, done, total| {
337:                 let _ = tx2.send(Event::Job(JobEvent::Progress { id, done, total, current: name.to_string() }));
338:             });
339:             match r {
340:                 Ok((n, bytes)) => {
341:                     let _ = tx.send(Event::Job(JobEvent::Finished { id, created: vec![dest.clone()], touched: vec![dest.clone()] }));
342:                     let _ = tx.send(Event::Message { text: format!("Extracted {} files ({}) into {}", n, crate::model::format_size(bytes), dest.name()), ok: true });
343:                     let _ = tx.send(Event::ArchiveDone { loc: src, ok: true, detail: format!("{} files", n) });
344:                 }
345:                 Err(e) => {
346:                     let _ = tx.send(Event::Job(JobEvent::Failed { id, error: e.to_string() }));
347:                 }
348:             }
349:         });
350:     }
