352:     pub fn archive_compress(&self, srcs: Vec<Location>, dest_zip: Location, password: Option<String>, level: u8) {
353:         let (reg, tx, id) = (self.registry.clone(), self.tx.clone(), self.id());
354:         let title = format!("Creating {}", dest_zip.name());
355:         let _ = tx.send(Event::Job(JobEvent::Started { id, title }));
356:         spawn(move || {
357:             let tx2 = tx.clone();
358:             let r = crate::archive::compress(&reg, &srcs, &dest_zip, password, level, |name, done, total| {
359:                 let _ = tx2.send(Event::Job(JobEvent::Progress { id, done, total, current: name.to_string() }));
360:             });
361:             match r {
362:                 Ok((n, _)) => {
363:                     let parent = dest_zip.parent().unwrap_or_else(|| dest_zip.clone());
364:                     let _ = tx.send(Event::Job(JobEvent::Finished { id, created: vec![dest_zip.clone()], touched: vec![parent] }));
365:                     let _ = tx.send(Event::Message { text: format!("Compressed {} files into {}", n, dest_zip.name()), ok: true });
366:                     let _ = tx.send(Event::ArchiveDone { loc: dest_zip, ok: true, detail: format!("{} files", n) });
367:                 }
368:                 Err(e) => {
369:                     let _ = tx.send(Event::Job(JobEvent::Failed { id, error: e.to_string() }));
370:                 }
371:             }
372:         });
373:     }
