385:     /// Files currently sitting in the user's Trash. On the web this is empty.
386:     pub fn trash_entries(&self) -> Vec<Entry> {
387:         #[cfg(not(target_arch = "wasm32"))]
388:         {
389:             let Some(dir) = Self::trash_dir() else { return vec![] };
390:             let mut out = vec![];
391:             if let Ok(rd) = std::fs::read_dir(dir.join("files")) {
392:                 for e in rd.flatten() {
393:                     let p = e.path();
394:                     let meta = e.metadata().ok();
395:                     let modified = meta.as_ref().and_then(|m| m.modified().ok()).and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok()).map(|d| d.as_secs() as i64);
396:                     out.push(Entry::new(Location::new("file", p.to_string_lossy().to_string()), p.is_dir(), meta.as_ref().map(|m| m.len()).unwrap_or(0), modified));
397:                 }
398:             }
399:             out.sort_by(|a, b| b.modified.cmp(&a.modified));
400:             out
401:         }
402:         #[cfg(target_arch = "wasm32")]
403:         {
404:             let _ = self;
405:             vec![]
406:         }
407:     }
