409:     /// Permanently delete everything in the Trash. Returns how many items were removed.
410:     pub fn trash_empty(&self) -> Result<usize, String> {
411:         #[cfg(not(target_arch = "wasm32"))]
412:         {
413:             let Some(dir) = Self::trash_dir() else { return Ok(0) };
414:             let mut n = 0;
415:             for sub in ["files", "info"] {
416:                 if let Ok(rd) = std::fs::read_dir(dir.join(sub)) {
417:                     for e in rd.flatten() {
418:                         let p = e.path();
419:                         let r = if p.is_dir() { std::fs::remove_dir_all(&p) } else { std::fs::remove_file(&p) };
420:                         if r.is_ok() {
421:                             n += 1;
422:                         }
423:                     }
424:                 }
425:             }
426:             Ok(n)
427:         }
428:         #[cfg(target_arch = "wasm32")]
429:         {
430:             let _ = self;
431:             Ok(0)
432:         }
433:     }
