435:     /// Restore a trashed item to the path recorded in its .trashinfo file.
436:     pub fn trash_restore(&self, loc: &Location) -> Result<Location, String> {
437:         #[cfg(not(target_arch = "wasm32"))]
438:         {
439:             let dir = Self::trash_dir().ok_or("no Trash on this system")?;
440:             let name = loc.name();
441:             let info = dir.join("info").join(format!("{name}.trashinfo"));
442:             let mut dest: Option<std::path::PathBuf> = None;
443:             if let Ok(txt) = std::fs::read_to_string(&info) {
444:                 for line in txt.lines() {
445:                     if let Some(v) = line.strip_prefix("Path=") {
446:                         let v = v.trim();
447:                         dest = Some(if v.starts_with('/') { std::path::PathBuf::from(v) } else { std::env::var_os("HOME").map(std::path::PathBuf::from).unwrap_or_default().join(v) });
448:                     }
449:                 }
450:             }
451:             let dest = dest.unwrap_or_else(|| std::env::var_os("HOME").map(std::path::PathBuf::from).unwrap_or_default().join(&name));
452:             let dest = if dest.exists() {
453:                 let mut d = dest.clone();
454:                 let mut i = 1;
455:                 while d.exists() {
456:                     let stem = dest.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
457:                     let ext = dest.extension().map(|e| format!(".{}", e.to_string_lossy())).unwrap_or_default();
458:                     d = dest.with_file_name(format!("{stem} ({i}){ext}"));
459:                     i += 1;
460:                 }
461:                 d
462:             } else {
463:                 dest
464:             };
465:             if let Some(par) = dest.parent() {
466:                 let _ = std::fs::create_dir_all(par);
467:             }
468:             std::fs::rename(&loc.path, &dest).map_err(|e| format!("could not restore: {e}"))?;
469:             let _ = std::fs::remove_file(info);
470:             Ok(Location::new("file", dest.to_string_lossy().to_string()))
471:         }
472:         #[cfg(target_arch = "wasm32")]
473:         {
474:             let _ = (self, loc);
475:             Err("not available in the web preview".into())
476:         }
477:     }
