526:     fn device_op(&self, id: &str, op: &'static str) {
527:         let (providers, tx, reg, id) = (self.providers.clone(), self.tx.clone(), self.registry.clone(), id.to_string());
528:         let store = self.devices.clone();
529:         spawn(move || {
530:             let Some(p) = providers.iter().find(|p| p.owns(&id)) else {
531:                 let _ = tx.send(Event::DeviceOp { id, op, result: Err("Unknown device".into()) });
532:                 return;
533:             };
534:             let result = match op {
535:                 "mount" => p.mount(&id).map(|m| {
536:                     if let Some(v) = m.vfs {
537:                         reg.insert(v);
538:                     }
539:                     Some(m.loc)
540:                 }),
541:                 "eject" => p.eject(&id).map(|_| None),
542:                 _ => p.unmount(&id).map(|_| None),
543:             };
544:             let all: Vec<Device> = providers.iter().flat_map(|p| p.list()).collect();
545:             *store.lock().unwrap() = all.clone();
546:             let _ = tx.send(Event::DeviceOp { id, op, result });
547:             let _ = tx.send(Event::Devices(all));
548:         });
549:     }
