592:     fn launch(&self, loc: &Location, app: Option<AppInfo>) {
593:         self.library.write().unwrap().touch_recent(loc);
594:         let (reg, tx, apps, loc) = (self.registry.clone(), self.tx.clone(), self.apps.clone(), loc.clone());
595:         spawn(move || {
596:             let name = loc.name();
597:             let real = reg.get(&loc.fs).and_then(|v| v.real_path(&loc.path));
598:             #[cfg(not(target_arch = "wasm32"))]
599:             let real = real.or_else(|| {
600:                 // Remote provider: stage a temporary local copy, then hand it to the OS.
601:                 let v = reg.get(&loc.fs)?;
602:                 let dir = std::env::temp_dir().join("smart-files-open");
603:                 std::fs::create_dir_all(&dir).ok()?;
604:                 let p = dir.join(&name);
605:                 let mut r = v.open_read(&loc.path).ok()?;
606:                 let mut w = std::fs::File::create(&p).ok()?;
607:                 std::io::copy(&mut r, &mut w).ok()?;
608:                 Some(p)
609:             });
610:             let res = match &app {
611:                 Some(a) => apps.open_with(a, &name, real.as_deref()),
612:                 None => apps.open_default(&name, real.as_deref()),
613:             };
614:             let (text, ok) = match res {
615:                 Ok(t) => (t, true),
616:                 Err(e) => (e, false),
617:             };
618:             let _ = tx.send(Event::Message { text, ok });
619:         });
620:     }
