634:     // ───────── pump ─────────
635:     pub fn poll(&mut self) -> Vec<Event> {
636:         let mut out: Vec<Event> = vec![];
637:         // paced (showcase) transfers: progress is driven by wall-clock time so the UI animates smoothly
638:         let now = crate::exec::now_millis();
639:         let mut finished: Vec<(u64, JobKind)> = vec![];
640:         {
641:             let mut q = self.paced.lock().unwrap();
642:             q.retain_mut(|j| {
643:                 let frac = ((now - j.started_ms) as f32 / 1000.0) / j.secs;
644:                 if now - j.last >= 16 || frac >= 1.0 {
645:                     j.last = now;
646:                     let total = 1000u64;
