659:                 Ok((created, touched)) => {
660:                     for t in &touched {
661:                         self.search.invalidate(t);
662:                     }
663:                     let n = created.len();
664:                     out.push(Event::Job(JobEvent::Finished { id, created, touched }));
665:                     let verb = match kind { JobKind::Move { .. } => "Moved", _ => "Copied" };
666:                     out.push(Event::Message { text: format!("{} {} item{}", verb, n, if n == 1 { "" } else { "s" }), ok: true });
