679:             out.push(match m {
680:                 SearchMsg::Hits { id, hits } => Event::SearchHits { req: id, hits },
681:                 SearchMsg::Done { id, scanned, elapsed_ms, cached } => Event::SearchDone { req: id, scanned, elapsed_ms, cached },
682:             });
683:         }
684:         while let Ok(e) = self.rx.try_recv() {
685:             match &e {
686:                 Event::Changed(l) => self.search.invalidate(l),
687:                 Event::Job(JobEvent::Finished { touched, id, .. }) => {
688:                     for t in touched {
689:                         self.search.invalidate(t);
690:                     }
691:                     self.jobs.lock().unwrap().remove(id);
692:                 }
693:                 Event::Job(JobEvent::Failed { id, .. }) => {
694:                     self.jobs.lock().unwrap().remove(id);
695:                 }
696:                 _ => {}
697:             }
698:             out.push(e);
699:         }
700:         for t in self.thumbs.poll() {
701:             out.push(Event::Thumb(t));
702:         }
703:     }
