259: impl Scorer {
260:     fn new(terms: &[String]) -> Self {
261:         Self {
262:             matcher: Matcher::new(Config::DEFAULT.match_paths()),
263:             pats: terms.iter().map(|t| Pattern::parse(t, CaseMatching::Smart, Normalization::Smart)).collect(),
264:             terms: terms.iter().map(|t| t.to_lowercase()).collect(),
265:             buf: Vec::new(),
266:         }
267:     }
268:     fn score(&mut self, e: &IndexEntry) -> Option<u32> {
269:         if self.pats.is_empty() {
270:             return Some(1);
271:         }
272:         let mut total = 0u32;
273:         for p in &self.pats {
274:             match p.score(Utf32Str::new(&e.name, &mut self.buf), &mut self.matcher) {
275:                 Some(s) => total += s * 4,
276:                 None => total += p.score(Utf32Str::new(&e.path, &mut self.buf), &mut self.matcher)?,
277:             }
278:         }
279:         // cheap tie-breakers (only on matches): prefix / exact names, short names, fresh files, folders
280:         let n = e.name.to_lowercase();
281:         for t in &self.terms {
282:             if n == *t || n.rsplit_once('.').is_some_and(|(s, _)| s == t) {
283:                 total += 600;
284:             } else if n.starts_with(t.as_str()) {
285:                 total += 240;
286:             }
287:         }
288:         total = total.saturating_sub(e.name.len() as u32);
289:         if e.modified > now_secs() - 7 * 86400 {
290:             total += 24;
291:         }
292:         if e.dir {
293:             total += 12;
294:         }
295:         Some(total)
296:     }
297:     fn indices(&mut self, name: &str) -> Vec<u32> {
298:         let mut out = vec![];
299:         for p in &self.pats {
300:             let mut idx = vec![];
301:             if p.indices(Utf32Str::new(name, &mut self.buf), &mut self.matcher, &mut idx).is_some() {
302:                 out.extend(idx);
303:             }
304:         }
305:         out.sort_unstable();
306:         out.dedup();
307:         out
308:     }
309: }
