311: fn passes(f: &Filters, e: &IndexEntry, fs: &str, lib: &SharedLibrary) -> bool {
312:     if let Some(d) = f.dirs {
313:         if e.dir != d {
314:             return false;
315:         }
316:     }
317:     if !f.kinds.is_empty() && !f.kinds.contains(&e.kind) {
318:         return false;
