412: fn score_all(entries: &[IndexEntry], terms: &[String], f: &Filters, fs: &str, lib: &SharedLibrary, root: &str) -> Vec<(u32, usize)> {
413:     use rayon::prelude::*;
414:     entries
415:         .par_chunks(16_384)
416:         .enumerate()
417:         .flat_map_iter(|(ci, chunk)| {
418:             let mut s = Scorer::new(terms);
419:             chunk
420:                 .iter()
421:                 .enumerate()
422:                 .filter_map(|(i, e)| {
423:                     if !under(&e.path, root) || !passes(f, e, fs, lib) {
424:                         return None;
425:                     }
426:                     s.score(e).map(|sc| (sc, ci * 16_384 + i))
427:                 })
428:                 .collect::<Vec<_>>()
429:         })
430:         .collect()
431: }
