433: fn score_all(entries: &[IndexEntry], terms: &[String], f: &Filters, fs: &str, lib: &SharedLibrary, root: &str) -> Vec<(u32, usize)> {
434:     let mut s = Scorer::new(terms);
435:     entries
436:         .iter()
437:         .enumerate()
438:         .filter_map(|(i, e)| if under(&e.path, root) && passes(f, e, fs, lib) { s.score(e).map(|sc| (sc, i)) } else { None })
439:         .collect()
