446: fn content_filter(v: &dyn Vfs, cands: Vec<(u32, IndexEntry)>, needle: &str) -> Vec<(u32, IndexEntry, Option<String>)> {
447:     let mut cands: Vec<_> = cands.into_iter().filter(|(_, e)| text_like(e)).collect();
448:     cands.sort_by(|a, b| b.1.modified.cmp(&a.1.modified));
449:     cands.truncate(6000);
450:     #[cfg(not(target_arch = "wasm32"))]
451:     {
452:         use rayon::prelude::*;
453:         cands.into_par_iter().filter_map(|(s, e)| content_hit(v, &e, needle).map(|sn| (s + 50, e, Some(sn)))).collect()
454:     }
455:     #[cfg(target_arch = "wasm32")]
456:     {
457:         cands.into_iter().filter_map(|(s, e)| content_hit(v, &e, needle).map(|sn| (s + 50, e, Some(sn)))).collect()
458:     }
459: }
