214:             LoopMode::Ab { a, b: Some(b) } => format!("Looping {} \u{2192} {}", crate::fmt_time_ms(a), crate::fmt_time_ms(b)),
215:             _ => "Loop cleared".to_string(),
216:         };
217:         self.say(m);
218:     }
219:     pub fn toggle_loop_file(&mut self) {
220:         self.looping = if self.looping == LoopMode::File { LoopMode::Off } else { LoopMode::File };
221:         self.say(if self.looping == LoopMode::File { "Repeat file" } else { "Repeat off" });
222:     }
223: 
224:     pub fn next_chapter(&mut self) -> Vec<Event> {
225:         match self.chapters.iter().cloned().find(|c| *c > self.position + 0.5) {
226:             Some(c) => self.seek_abs(c),
227:             None => vec![],
228:         }
229:     }
230:     pub fn prev_chapter(&mut self) -> Vec<Event> {
231:         // within the first 3 s of a chapter, jump to the previous one; otherwise restart this one
232:         let cur = self.chapters.iter().cloned().filter(|c| *c <= self.position - 3.0).last();
233:         match cur {
234:             Some(c) => self.seek_abs(c),
235:             None => self.seek_abs(0.0),
236:         }
237:     }
238:     pub fn chapter_index(&self) -> Option<usize> {
239:         self.chapters.iter().rposition(|c| *c <= self.position + 0.01)
240:     }
241: }
