538: /// Applies a subtitle delay step and returns the OSD text.
539: pub fn nudge_sub_delay(t: &mut SubTrack, d: f64) -> String {
540:     t.delay = ((t.delay + d) * 1000.0).round() / 1000.0;
541:     format!("Subtitle delay {:+.0} ms", t.delay * 1000.0)
542: }
