185: fn put(buf: &mut [u8], w: usize, x: usize, y: usize, c: [u8; 3]) {
186:     let i = (y * w + x) * 4;
187:     if i + 3 < buf.len() {
188:         buf[i] = c[0];
189:         buf[i + 1] = c[1];
190:         buf[i + 2] = c[2];
191:         buf[i + 3] = 255;
192:     }
193: }
