195: fn draw_text(buf: &mut [u8], w: usize, h: usize, x0: usize, y0: usize, scale: usize, text: &str, c: [u8; 3]) {
196:     let mut x = x0;
197:     for ch in text.chars() {
198:         let g = match ch {
199:             '0'..='9' => GLYPHS[ch as usize - '0' as usize],
200:             ':' => GLYPHS[10],
201:             _ => GLYPHS[11],
202:         };
203:         for (row, bits) in g.iter().enumerate() {
204:             for col in 0..5 {
205:                 if bits & (1 << (4 - col)) != 0 {
206:                     for dy in 0..scale {
207:                         for dx in 0..scale {
208:                             let (px, py) = (x + col * scale + dx, y0 + row * scale + dy);
209:                             if px < w && py < h {
210:                                 put(buf, w, px, py, c);
211:                             }
212:                         }
213:                     }
214:                 }
215:             }
216:         }
217:         x += 6 * scale;
218:     }
219: }
