fi

echo "==> [4/4] pack AppImage"
OUT="$SF/Smart-Files-x86_64.AppImage"
ARCH=x86_64 APPIMAGE_EXTRACT_AND_RUN=1 "$TOOL" "$APPDIR" "$OUT"
chmod +x "$OUT"
echo
echo "Done: $OUT"
echo "Run it:  $OUT      (works on Wayfire, Gnome X11, any glibc distro)"
