    /// Sparse content of the given size (reads as zeros). Lets the demo hold a 5 GB file in a browser.
    Synth(u64),
}
impl Content {
    fn len(&self) -> u64 {
        match self {
            Content::Static(s) => s.len() as u64,
            Content::Sized(_, n) => *n,
            Content::Buf(b) => b.len() as u64,
            Content::Synth(n) => *n,
