306:     fn item_interaction(&mut self, ui: &Ui, i: usize, hit: Rect, e: &Entry) -> egui::Response {
307:         let resp = ui.interact(hit, Id::unique(("item", &e.loc)), Sense::click_and_drag());
308:         ITEM_RECTS.with(|v| v.borrow_mut().push((e.loc.clone(), hit)));
309:         // Selection model: a plain click only *focuses* (soft highlight). Ticks, long-press, Ctrl/Shift-click, marquee
310:         // and Select All enter selection mode, where a plain click toggles.
311:         let long = resp.long_touched();
312:         if long || resp.clicked() {
313:             let m = ui.input(|i| i.modifiers);
314:             let multi_key = m.command || m.ctrl;
315:             if long {
316:                 self.toggle_tick(&e.loc);
317:                 self.anchor = Some(i);
318:             } else if m.shift && self.anchor.is_some() {
319:                 let a = self.anchor.unwrap();
320:                 let (lo, hi) = (a.min(i), a.max(i));
321:                 self.sel = self.items[lo..=hi].iter().map(|e| e.loc.clone()).collect();
322:                 self.select_mode = true;
323:             } else if multi_key || self.select_mode {
324:                 self.toggle_tick(&e.loc);
325:                 self.anchor = Some(i);
326:             } else {
327:                 self.sel.clear();
328:                 self.sel.insert(e.loc.clone());
329:                 self.anchor = Some(i);
330:             }
331:             self.focus = Some(i);
332:         }
333:         if resp.double_clicked() {
334:             self.acts.push(Act::Open(e.loc.clone()));
335:         }
336:         if resp.secondary_clicked() {
337:             if !self.sel.contains(&e.loc) {
338:                 self.sel.clear();
339:                 self.sel.insert(e.loc.clone());
340:             }
341:             self.menu = Some(Menu { kind: MenuKind::Item, pos: ui.ctx().pointer_latest_pos().unwrap_or(hit.center()), target: Some(e.loc.clone()), device: None, sub: None, age: 0.0 });
342:         }
343:         if resp.drag_started() {
344:             if !self.sel.contains(&e.loc) {
345:                 self.sel.clear();
346:                 self.sel.insert(e.loc.clone());
347:             }
348:             let items: Vec<Location> = self.selected().iter().map(|x| x.loc.clone()).collect();
349:             let label = if items.len() == 1 { e.name.clone() } else { format!("{} items", items.len()) };
350:             self.drag = Some(Drag { items, label });
351:         }
352:         resp
353:     }
