355:     fn name_or_rename(&mut self, ui: &mut Ui, e: &Entry, pos: Pos2, max_w: f32, font: egui::FontId, col: Color32) -> f32 {
356:         let p = ui.painter().clone();
357:         if self.rename.as_ref().is_some_and(|r| r.loc == e.loc) {
358:             let rr = Rect::from_min_size(pos + vec2(-4.0, -11.0), vec2(max_w + 8.0, 22.0));
359:             grad_fill(&p, rr, 7.0, self.th.panel_top, self.th.panel_bottom);
360:             p.rect_stroke(rr.expand(1.0), cr(8.0), egui::Stroke::new(2.0, alpha(self.th.accent, 0.7)), egui::StrokeKind::Outside);
361:             let mut text = self.rename.as_ref().map(|r| r.text.clone()).unwrap_or_default();
362:             let first = self.rename.as_ref().is_some_and(|r| r.first);
363:             let id = Id::unique(("rename", &e.loc));
364:             let out = ui.put(rr.shrink2(vec2(4.0, 0.0)), egui::TextEdit::singleline(&mut text).id(id).frame(egui::Frame::NONE).font(font).text_color(self.th.ink1).vertical_align(egui::Align::Center).margin(egui::Margin::ZERO));
365:             if first {
366:                 out.request_focus();
367:                 if let Some(mut st) = egui::TextEdit::load_state(ui.ctx(), id) {
368:                     let stem = text.rfind('.').filter(|i| *i > 0 && !e.is_dir).map(|i| text[..i].chars().count()).unwrap_or(text.chars().count());
369:                     st.cursor.set_char_range(Some(egui::text::CCursorRange::two(egui::text::CCursor::new(0), egui::text::CCursor::new(stem))));
370:                     st.store(ui.ctx(), id);
371:                 }
372:                 if let Some(r) = self.rename.as_mut() {
373:                     r.first = false;
374:                 }
375:             }
376:             let enter = ui.input(|i| i.key_pressed(egui::Key::Enter));
377:             let esc = ui.input(|i| i.key_pressed(egui::Key::Escape));
378:             if let Some(r) = self.rename.as_mut() {
379:                 r.text = text.clone();
380:             }
381:             if enter || esc || (out.lost_focus() && !first) {
382:                 let loc = e.loc.clone();
383:                 self.rename = None;
384:                 if !esc {
385:                     match self.be.rename(&loc, &text) {
386:                         Ok(n) => {
387:                             self.select_after_list = vec![n];
388:                             self.load();
389:                         }
390:                         Err(m) => self.toast(m, false),
391:                     }
392:                 }
393:             }
394:             return max_w;
395:         }
396:         let display = if !self.st().show_extensions && !e.is_dir && !e.ext.is_empty() { e.name.trim_end_matches(&format!(".{}", e.ext)).to_string() } else { e.name.clone() };
397:         let t = self.fit(&p, &display, &font, max_w);
398:         let r = p.text(pos, Align2::LEFT_CENTER, t, font, col);
399:         r.width()
400:     }
