458:     fn folder_card(&mut self, ui: &mut Ui, i: usize, r: Rect) {
459:         let e = self.items[i].clone();
460:         let th = self.th.clone();
461:         let resp = self.item_interaction(ui, i, r, &e);
462:         let p = ui.painter().clone();
463:         let dragging = self.drag.is_some();
464:         let dropping = dragging && ui.rect_contains_pointer(r) && self.drag.as_ref().is_some_and(|d| !d.items.contains(&e.loc));
465:         let hov = resp.hovered();
466:         let a = self.anim(ui, ("fc", &e.loc), hov);
467:         let r = r.translate(vec2(0.0, -2.0 * a));
468:         let selected = self.sel.contains(&e.loc);
469:         let checked = selected && self.select_mode;
470:         DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Folder(e.loc.clone()), r)));
471:         elevate(&p, &th, r, 16.0, if a > 0.01 || dropping { 3 } else { 2 });
472:         grad_fill(&p, r, 16.0, mix(th.card_top, th.card_hover_top, a), th.card_bottom);
473:         rim(&p, r, 16.0, 1.3, th.rim, true, 36.0);
474:         rim(&p, r, 16.0, 1.0, th.rim_under, false, 6.0);
475:         if checked || dropping {
476:             grad_fill(&p, r, 16.0, th.accent_tint, th.accent_tint2);
477:             self.selection_ring(&p, r, 16.0);
478:         } else if selected {
479:             self.focus_ring(&p, r, 16.0);
480:         }
481:         let tile = Rect::from_min_size(r.min + vec2(12.0, 12.0), vec2(46.0, 46.0));
482:         grad_fill(&p, tile, 13.0, mix(th.accent_tint, Color32::WHITE, if th.dark { 0.0 } else { 0.55 }), alpha(th.accent, if th.dark { 0.20 } else { 0.16 }));
483:         rim(&p, tile, 13.0, 1.0, alpha(Color32::WHITE, if th.dark { 0.14 } else { 0.9 }), true, 18.0);
484:         self.ico(&p, if dropping { "folder-open" } else { "folder" }, Ic::Filled, tile.center(), 24.0, th.accent);
485:         let tx = tile.right() + 12.0;
486:         let max_w = r.right() - tx - 30.0;
487:         self.name_or_rename(ui, &e, pos2(tx, r.top() + 27.0), max_w, f_semi(T_BODY), th.ink1);
488:         let meta = match self.summaries.get(&e.loc) {
489:             Some((n, b)) => format!("{} item{} \u{b7} {}", n, if *n == 1 { "" } else { "s" }, format_size(*b)),
490:             None => "\u{2014}".into(),
491:         };
492:         p.text(pos2(tx, r.top() + 45.0), Align2::LEFT_CENTER, self.fit(&p, if dropping { "Drop to move here" } else { &meta }, &f_medium(T_META), max_w), f_medium(T_META), if dropping { th.accent_ink } else { th.ink3 });
493:         let n = self.tag_colors(&e.loc).len();
494:         self.tag_dots(&p, &e, r.right() - 14.0 - 11.0 * n as f32 + 3.0, r.center().y, r.right());
495:         if a > 0.05 || checked || self.select_mode {
496:             if self.tick_badge(ui, r.left_top() + vec2(12.0, 12.0), ("fchk", &e.loc), checked, 20.0) {
497:                 self.toggle_tick(&e.loc);
498:             }
499:         }
500:     }
