502:     fn file_card(&mut self, ui: &mut Ui, i: usize, r: Rect, mh: f32) {
503:         let e = self.items[i].clone();
504:         let th = self.th.clone();
505:         self.request_thumb_for(&e);
506:         let resp = self.item_interaction(ui, i, r, &e);
507:         let p = ui.painter().clone();
508:         let hov = resp.hovered();
509:         let a = self.anim(ui, ("fl", &e.loc), hov);
510:         let lift = -2.0 * a;
511:         let media = Rect::from_min_size(r.min + vec2(0.0, lift), vec2(r.width(), mh));
512:         let selected = self.sel.contains(&e.loc);
513:         let checked = selected && self.select_mode;
514:         elevate(&p, &th, media, 14.0, if a > 0.01 { 3 } else { 2 });
515:         if let Some(t) = self.thumbs.get(&e.loc) {
516:             let sz = t.tex.size_vec2();
517:             textured_rrect(&p, media, 14.0, t.tex.id(), cover_uv(sz.x, sz.y, media), Color32::WHITE);
518:         } else {
519:             let kc = kind_color(e.kind, &th);
520:             grad_fill(&p, media, 14.0, mix(th.card_top, kc, if th.dark { 0.22 } else { 0.10 }), mix(th.card_bottom, kc, if th.dark { 0.12 } else { 0.18 }));
521:             let c = media.center();
522:             let tile = Rect::from_center_size(c, vec2(64.0, 64.0));
523:             grad_fill(&p, tile, 20.0, alpha(kc, 0.20), alpha(kc, 0.10));
524:             self.ico(&p, e.kind.icon(), Ic::Duo, c, 32.0, kc);
525:             if !e.ext.is_empty() {
526:                 p.text(pos2(c.x, media.bottom() - 18.0), Align2::CENTER_CENTER, e.ext.to_uppercase(), f_bold(10.5), alpha(kc, 0.9));
527:             }
528:         }
529:         rim(&p, media, 14.0, 1.2, alpha(Color32::WHITE, if th.dark { 0.14 } else { 0.55 }), true, 24.0);
530:         if checked {
531:             grad_fill(&p, media, 14.0, alpha(th.accent, 0.10), alpha(th.accent, 0.04));
532:             self.selection_ring(&p, media, 14.0);
533:         } else if selected {
534:             self.focus_ring(&p, media, 14.0);
535:         }
536:         // 5 GB demo badge
537:         if e.paced {
538:             let f = f_semi(9.5);
539:             let w = self.tw(&p, "5 GB DEMO", &f) + 16.0;
540:             let b = Rect::from_min_size(media.left_bottom() + vec2(9.0, -25.0), vec2(w, 18.0));
541:             grad_fill(&p, b, 9.0, alpha(th.accent, 0.9), alpha(th.accent_press, 0.9));
542:             p.text(b.center(), Align2::CENTER_CENTER, "5 GB DEMO", f, th.on_accent());
543:         }
544:         if e.kind == Kind::Audio {
545:             let playing = self.audio_loc.as_ref() == Some(&e.loc) && self.be.audio.is_playing();
546:             if hov || playing {
547:                 let b = Rect::from_center_size(media.center(), vec2(44.0, 44.0));
548:                 let br = self.hit(ui, b, ("play", &e.loc), Sense::click());
549:                 raised_accent(&p, &th, b, 22.0, br.hovered(), br.is_pointer_button_down_on());
550:                 self.ico(&p, if playing { "pause" } else { "play" }, Ic::Filled, b.center() + vec2(if playing { 0.0 } else { 1.0 }, 0.0), 18.0, th.on_accent());
551:                 if br.clicked() {
552:                     self.acts.push(Act::TogglePlayPause(e.loc.clone()));
553:                 }
554:             }
555:         }
556:         if a > 0.05 || checked || self.select_mode {
557:             if self.tick_badge(ui, media.left_top() + vec2(19.0, 19.0), ("chk", &e.loc), checked, 22.0) {
558:                 self.toggle_tick(&e.loc);
559:             }
560:             if a > 0.05 {
561:                 let q = Rect::from_center_size(media.right_top() + vec2(-23.0, 23.0), vec2(30.0, 30.0));
562:                 let qr = self.hit(ui, q, ("qa", &e.loc), Sense::click());
563:                 raised(&p, &th, q, 15.0, qr.hovered(), qr.is_pointer_button_down_on());
564:                 self.ico(&p, "menu-dots", Ic::Duo, q.center(), 15.0, th.ink2);
565:                 if qr.clicked() {
566:                     self.sel.clear();
567:                     self.sel.insert(e.loc.clone());
568:                     self.menu = Some(Menu { kind: MenuKind::Item, pos: pos2(q.right(), q.bottom() + 6.0), target: Some(e.loc.clone()), device: None, sub: None, age: 0.0 });
569:                 }
570:                 if e.kind.previewable() && e.kind != Kind::Audio {
571:                     let q2 = Rect::from_center_size(media.right_top() + vec2(-59.0, 23.0), vec2(30.0, 30.0));
572:                     let qr2 = self.hit(ui, q2, ("qe", &e.loc), Sense::click());
573:                     raised(&p, &th, q2, 15.0, qr2.hovered(), qr2.is_pointer_button_down_on());
574:                     self.ico(&p, "eye", Ic::Duo, q2.center(), 15.0, th.ink3);
575:                     if qr2.clicked() {
576:                         self.acts.push(Act::Preview(e.loc.clone()));
577:                     }
578:                 }
579:             }
580:         }
581:         let ty = media.bottom() + 16.0 - lift;
582:         let max_w = r.width() - 6.0 - 12.0 * self.tag_colors(&e.loc).len() as f32;
583:         let wname = self.name_or_rename(ui, &e, pos2(r.left() + 3.0, ty), max_w, f_semi(T_BODY), th.ink1);
584:         self.tag_dots(&p, &e, r.left() + 3.0 + wname + 7.0, ty + 0.5, r.right());
585:         let date = e.modified.map(format_date).unwrap_or_default();
586:         let meta = format!("{}  \u{b7}  {}", format_size(e.size), date);
587:         p.text(pos2(r.left() + 3.0, ty + 19.0), Align2::LEFT_CENTER, meta, f_medium(T_META), th.ink3);
588:     }
