218:                 w.placed = true;
219:                 w.restore = None;
220:             }
221:             self.draw_app(ui, a, screen);
222:             self.draw_app_menu(ui, screen);
223:             crate::overlays::WIN_RECT.with(|c| c.set(win));
224:             return;
225:         }
226:         clear_drop_targets();
227:         let screen = ui.max_rect();
228:         let p = ui.painter().clone();
229:         self.draw_desktop(&p, screen);
230:         self.shell_focus(ui, screen);
231:         for id in self.shell.z.clone() {
232:             match id {
233:                 AppId::Files => {
234:                     if !(self.win_closed || self.win_min) {
235:                         self.draw_files_window(ui);
236:                     }
237:                 }
238:                 _ => self.draw_app(ui, id, screen),
239:             }
240:         }
241:         self.draw_app_menu(ui, screen);
242:         self.draw_dock(ui, screen);
243:         self.draw_topbar(ui, screen);
244:         let b = self.shell.brightness;
245:         if b < 0.99 {
246:             let lp = ui.ctx().layer_painter(egui::LayerId::new(egui::Order::Tooltip, Id::new("dim")));
247:             lp.rect_filled(screen, 0.0, Color32::from_black_alpha(((1.0 - b) * 150.0) as u8));
248:         }
249:     }
