251:     /// Pressing inside a window raises it; the top bar and dock never steal focus.
252:     fn shell_focus(&mut self, ui: &Ui, screen: Rect) {
253:         let Some(pos) = ui.input(|i| if i.pointer.primary_pressed() { i.pointer.interact_pos() } else { None }) else { return };
254:         if pos.y < TOPBAR_H || pos.y > screen.bottom() - 70.0 {
255:             return;
256:         }
257:         for id in self.shell.z.clone().into_iter().rev() {
258:             let r = match id {
259:                 AppId::Files => {
260:                     if self.win_closed || self.win_min {
261:                         continue;
262:                     }
263:                     self.window_rect(screen)
264:                 }
265:                 other => {
266:                     let w = self.app_win(other).unwrap();
267:                     if !w.open || w.min {
268:                         continue;
269:                     }
270:                     w.rect
271:                 }
272:             };
273:             if r.contains(pos) {
274:                 if self.focused_app() != id {
275:                     self.raise(id);
276:                 }
277:                 break;
278:             }
279:         }
280:     }
