282:     // ───────────── app window frame ─────────────
283:     /// Unified macOS-style window: the sidebar runs the full height (traffic lights live in it), the toolbar shares the
284:     /// surface with the content (no title bar, no divider) and the whole thing resizes from every edge.
285:     fn draw_app(&mut self, ui: &mut Ui, id: AppId, screen: Rect) {
286:         let (open, min) = {
287:             let w = self.app_win(id).unwrap();
288:             (w.open, w.min)
289:         };
290:         if !open || min {
291:             return;
292:         }
293:         let avail = Rect::from_min_max(pos2(screen.left(), screen.top() + TOPBAR_H), pos2(screen.right(), screen.bottom() - 6.0));
294:         let n_open = self.shell.z.iter().position(|x| *x == id).unwrap_or(0) as f32;
295:         {
296:             let w = self.app_win_mut(id);
297:             if !w.placed {
298:                 let size = vec2(w.rect.width().min(avail.width() - 40.0), w.rect.height().min(avail.height() - DOCK_H * 0.6));
299:                 let c = avail.center() + vec2(40.0 + n_open * 18.0, 10.0 + n_open * 14.0 - 30.0);
300:                 w.rect = Rect::from_center_size(c, size);
301:                 w.placed = true;
302:             }
303:         }
304:         let (rect, born, restore, side_pref) = {
305:             let w = self.app_win(id).unwrap();
306:             (w.rect, w.born, w.restore, w.side)
307:         };
308:         let active = self.focused_app() == id;
309:         let th = self.th.clone();
310:         let ctx = ui.ctx().clone();
311:         let age = (self.time - born) as f32;
312:         let pop = if self.lib(|l| l.settings.reduce_motion) { 1.0 } else { spring_out(age) };
313:         if age < 0.7 {
314:             ctx.request_repaint();
315:         }
316:         let off = vec2(0.0, (1.0 - pop) * 28.0);
317:         let mut cui = ui.new_child(egui::UiBuilder::new().max_rect(screen));
318:         cui.set_opacity((age * 7.0).clamp(0.0, 1.0));
319:         let p = cui.painter().clone();
320:         let shown = rect.translate(off);
321:         elevate(&p, &th, shown, R_WIN, if active { 5 } else { 3 });
322:         // glass body (same recipe as the Files window)
323:         let (_, sz, blur) = self.active_wall();
324:         if let Some(b) = blur {
325:             let suv = cover_uv(sz[0], sz[1], screen);
326:             let f = |pt: Pos2| pos2(suv.min.x + (pt.x - screen.min.x) / screen.width() * suv.width(), suv.min.y + (pt.y - screen.min.y) / screen.height() * suv.height());
327:             textured_rrect(&p, shown, R_WIN, b, Rect::from_min_max(f(shown.min), f(shown.max)), Color32::from_white_alpha(if th.dark { 210 } else { 255 }));
328:         }
329:         grad_fill(&p, shown, R_WIN, th.window_top, th.window_bottom);
330:         // responsive: the sidebar folds away on narrow windows and comes back with a spring
331:         let want_side = side_pref && shown.width() >= 720.0;
332:         let sf = spring_to(&ctx, ("appside", id), if want_side { 1.0 } else { 0.0 }, 260.0, 26.0).clamp(0.0, 1.0);
333:         let side_w = SIDEBAR_W * sf;
334:         let sb = Rect::from_min_size(shown.min, vec2(side_w, shown.height()));
335:         let stage = Rect::from_min_max(pos2(shown.min.x + side_w, shown.min.y), shown.max);
336:         if side_w > 1.0 {
337:             let pp = p.with_clip_rect(sb);
338:             grad_fill(&pp, Rect::from_min_max(shown.min, pos2(shown.min.x + side_w + R_WIN + 4.0, shown.max.y)), R_WIN, th.sidebar_top, th.sidebar_bottom);
339:         }
340:         {
341:             let pp = p.with_clip_rect(stage);
342:             grad_fill(&pp, Rect::from_min_max(pos2(stage.min.x - R_WIN - 4.0, shown.min.y), shown.max), R_WIN, th.content_top, th.content_bottom);
343:         }
344:         // toolbar drag region (created first so controls on top win)
345:         let bar = Rect::from_min_size(stage.min, vec2(stage.width(), APPBAR_H));
346:         let drag = Rect::from_min_size(shown.min, vec2(shown.width(), APPBAR_H));
347:         let tresp = cui.interact(drag, Id::new(("apptitle", id)), Sense::click_and_drag());
348:         let mut maximise = tresp.double_clicked();
349:         if !IS_WEB && tresp.drag_started() {
350:             ctx.send_viewport_cmd(egui::ViewportCommand::StartDrag);
351:         }
352:         if tresp.dragged() && restore.is_none() {
353:             let d = tresp.drag_delta();
354:             let w = self.app_win_mut(id);
355:             w.rect = w.rect.translate(d);
356:             w.rect = w.rect.translate(vec2(0.0, (avail.top() - w.rect.top()).max(0.0)));
357:         }
358:         // traffic lights: in the sidebar when it is there, in the toolbar when it folds
359:         let cy = shown.top() + APPBAR_H / 2.0;
360:         let tl_x = shown.left() + 20.0;
361:         let (c1, c2, c3) = self.app_traffic(&cui, pos2(tl_x, cy), id, active);
362:         let mut do_close = c1;
363:         let mut do_min = c2;
364:         if c3 {
365:             maximise = true;
366:         }
367:         // sidebar toggle: owned by the toolbar, right after the traffic lights when the sidebar is folded
368:         let tx = bar.left() + 14.0 + (1.0 - sf) * 78.0 - if sf > 0.5 { 0.0 } else { 0.0 };
369:         let tx = if side_w > 40.0 { tx.max(bar.left() + 14.0) } else { shown.left() + 20.0 + 78.0 };
370:         let toggle = Rect::from_min_size(pos2(tx, cy - 17.0), vec2(34.0, 34.0));
371:         if self.icon_button(&cui, toggle, "sidebar-minimalistic", &format!("tb-side-{:?}", id), if side_pref { Btn::Raised } else { Btn::Tonal }, true).on_hover_text("Toggle sidebar  Ctrl+\\").clicked() {
372:             self.app_win_mut(id).side = !side_pref;
373:         }
374:         let side_body = Rect::from_min_max(pos2(shown.left(), shown.top() + 54.0), pos2(shown.left() + SIDEBAR_W, shown.bottom() - 10.0));
375:         let content = Rect::from_min_max(pos2(stage.left(), bar.bottom()), shown.max);
376:         let fr = crate::appkit::Frame { win: shown, side: sb, side_body, bar, stage: content, lead_x: toggle.right() + 12.0, right_x: bar.right() - 14.0, active };
377:         let mut cp = cui.new_child(egui::UiBuilder::new().max_rect(shown));
378:         cp.set_clip_rect(shown.intersect(screen));
379:         match id {
380:             AppId::Terminal => self.draw_terminal(&mut cp, &fr),
381:             AppId::Photos => self.draw_photos(&mut cp, &fr),
382:             AppId::Video => self.draw_eiga(&mut cp, &fr),
383:             AppId::Files => {}
384:         }
385:         if self.shell.settings.map(|s| s.0) == Some(id) {
386:             match id {
387:                 AppId::Terminal => self.term_settings(&mut cp, shown),
388:                 AppId::Photos => self.photos_settings(&mut cp, shown),
389:                 AppId::Video => self.eiga_settings(&mut cp, shown),
390:                 AppId::Files => {}
391:             }
392:         }
393:         // edge + corner resize (all eight handles)
394:         let min_sz = vec2(520.0, 340.0);
395:         if let Some((dir, d)) = self.resize_handles(&cui, id, shown) {
396:             if restore.is_none() {
397:                 let w = self.app_win_mut(id);
398:                 if dir.0 > 0.0 {
399:                     w.rect.max.x = (w.rect.max.x + d.x).max(w.rect.min.x + min_sz.x);
400:                 } else if dir.0 < 0.0 {
401:                     w.rect.min.x = (w.rect.min.x + d.x).min(w.rect.max.x - min_sz.x);
402:                 }
403:                 if dir.1 > 0.0 {
404:                     w.rect.max.y = (w.rect.max.y + d.y).max(w.rect.min.y + min_sz.y);
405:                 } else if dir.1 < 0.0 {
406:                     w.rect.min.y = (w.rect.min.y + d.y).min(w.rect.max.y - min_sz.y).max(avail.top());
407:                 }
408:             }
409:         }
410:         rim(&p, shown, R_WIN, 1.4, if th.dark { c(255, 255, 255, if active { 0.14 } else { 0.07 }) } else { c(255, 255, 255, 0.9) }, true, 42.0);
411:         // apply
412:         if do_close {
413:             self.app_win_mut(id).open = false;
414:             self.shell.settings = None;
415:             if id == AppId::Video {
416:                 self.eiga_cleanup();
417:             }
418:             do_close = false;
419:         }
420:         if do_min {
421:             self.app_win_mut(id).min = true;
422:             do_min = false;
423:         }
424:         let _ = (do_close, do_min);
425:         if maximise {
426:             let w = self.app_win_mut(id);
427:             if let Some(r) = w.restore.take() {
428:                 w.rect = r;
429:             } else {
430:                 w.restore = Some(w.rect);
431:                 w.rect = avail.shrink2(vec2(8.0, 4.0));
432:             }
433:         }
434:     }
