513:     fn draw_topbar(&mut self, ui: &mut Ui, screen: Rect) {
514:         let ctx = ui.ctx().clone();
515:         let th = self.th.clone();
516:         let p = ui.painter().clone();
517:         let bar = Rect::from_min_size(screen.min, vec2(screen.width(), TOPBAR_H));
518:         let (top, bot) = if th.dark { (c(10, 14, 24, 0.66), c(10, 14, 24, 0.50)) } else { (c(255, 255, 255, 0.62), c(244, 248, 255, 0.48)) };
519:         grad_fill(&p, bar, 0.0, top, bot);
520:         p.line_segment([bar.left_bottom(), bar.right_bottom()], egui::Stroke::new(1.0, if th.dark { c(255, 255, 255, 0.07) } else { c(255, 255, 255, 0.7) }));
521:         p.line_segment([bar.left_bottom() + vec2(0.0, 1.0), bar.right_bottom() + vec2(0.0, 1.0)], egui::Stroke::new(1.0, alpha(th.shadow, if th.dark { 0.3 } else { 0.06 })));
522:         let cy = bar.center().y;
523:         let app = self.focused_app();
524:         let app = if app == AppId::Files && (self.win_closed || self.win_min) { AppId::Files } else { app };
525:         let ink = if th.dark { th.ink1 } else { th.ink1 };
526: 
527:         // logo → Smart menu
528:         let mut x = bar.left() + 10.0;
529:         let logo = Rect::from_center_size(pos2(x + 13.0, cy), vec2(26.0, 22.0));
530:         let lr = self.hit(ui, logo, "tb-logo", Sense::click());
531:         if lr.hovered() || self.shell.menu == Some(0) {
532:             p.rect_filled(logo, cr(7.0), th.row_hover);
533:         }
534:         let lg = Rect::from_center_size(logo.center(), vec2(17.0, 17.0));
535:         let (a, b) = th.accent_grad();
536:         grad_fill(&p, lg, 6.0, a, b);
537:         rim(&p, lg, 6.0, 1.0, Color32::from_white_alpha(140), true, 8.0);
538:         p.text(lg.center() + vec2(0.0, 0.5), Align2::CENTER_CENTER, "S", f_bold(10.5), Color32::WHITE);
539:         let mut anchors: Vec<Rect> = vec![logo];
540:         if lr.clicked() {
541:             self.shell.menu = if self.shell.menu == Some(0) { None } else { Some(0) };
542:         }
543:         x = logo.right() + 8.0;
544:         p.text(pos2(x, cy), Align2::LEFT_CENTER, app.name(), f_bold(12.5), ink);
545:         x += self.tw(&p, app.name(), &f_bold(12.5)) + 12.0;
546:         let menus = self.tb_menus(app);
547:         for (i, (label, _)) in menus.iter().enumerate() {
548:             let w = self.tw(&p, label, &f_medium(12.5)) + 18.0;
549:             let r = Rect::from_min_size(pos2(x, cy - 11.0), vec2(w, 22.0));
550:             let resp = self.hit(ui, r, ("tb-menu", i), Sense::click());
551:             let open = self.shell.menu == Some(i + 1);
552:             if resp.hovered() || open {
553:                 p.rect_filled(r, cr(7.0), if open { th.row_press } else { th.row_hover });
554:             }
555:             p.text(r.center(), Align2::CENTER_CENTER, *label, f_medium(12.5), if open || resp.hovered() { ink } else { th.ink2 });
556:             if resp.clicked() {
557:                 self.shell.menu = if open { None } else { Some(i + 1) };
558:             } else if resp.hovered() && self.shell.menu.is_some() && !open {
559:                 self.shell.menu = Some(i + 1);
560:             }
561:             anchors.push(r);
562:             x += w + 2.0;
563:         }
564: 
565:         // right cluster: status icons + clock
566:         let mut rx = bar.right() - 12.0;
567:         let time = clock_hm();
568:         let date = clock_date();
569:         let tf = f_semi(12.5);
570:         let tw_ = self.tw(&p, &time, &tf);
571:         let dw = self.tw(&p, &date, &f_medium(12.5));
572:         let cluster_w = tw_ + dw + 16.0 + 4.0 * 26.0 + 14.0;
573:         let cluster = Rect::from_min_max(pos2(rx - cluster_w, cy - 12.0), pos2(rx + 4.0, cy + 12.0));
574:         let cresp = self.hit(ui, cluster, "tb-cluster", Sense::click());
575:         if cresp.hovered() || self.shell.qs {
576:             p.rect_filled(cluster, cr(8.0), if self.shell.qs { th.row_press } else { th.row_hover });
577:         }
578:         if cresp.clicked() {
579:             self.shell.qs = !self.shell.qs;
580:             self.shell.menu = None;
581:         }
582:         p.text(pos2(rx, cy), Align2::RIGHT_CENTER, &time, tf, ink);
583:         rx -= tw_ + 10.0;
584:         p.text(pos2(rx, cy), Align2::RIGHT_CENTER, &date, f_medium(12.5), th.ink2);
585:         rx -= dw + 14.0;
586:         let sh = &self.shell;
587:         let status: [(&'static str, bool); 4] = [("battery-charge-minimalistic", true), ("volume-small", sh.volume > 0.02), ("bluetooth", sh.bt), ("wi-fi", sh.wifi)];
588:         for (name, on) in status {
589:             self.ico(&p, name, Ic::Outline, pos2(rx - 9.0, cy), 15.0, if on { th.ink2 } else { alpha(th.ink4, 0.7) });
590:             rx -= 26.0;
591:         }
592: 
593:         // menu popovers
594:         if let Some(mi_idx) = self.shell.menu {
595:             let (items, anchor) = if mi_idx == 0 {
596:                 (
597:                     vec![
598:                         mi("info-circle", "About Smart Shell", Act::Seq(vec![Act::OpenApp(AppId::Files), Act::Modal(Modal::About)])),
599:                         mi("settings-minimalistic", "Settings\u{2026}", Act::Seq(vec![Act::OpenApp(AppId::Files), Act::Settings])).k("Ctrl+,").gap(),
600:                         mi("stars-minimalistic", if self.st().dark { "Switch to light" } else { "Switch to dark" }, Act::ToggleTheme).k("D"),
601:                         mi("gallery-wide", "Wallpaper\u{2026}", Act::Seq(vec![Act::OpenApp(AppId::Files), Act::Modal(Modal::Wallpaper)])),
602:                         mi("command", "Command palette", Act::Seq(vec![Act::OpenApp(AppId::Files), Act::Palette])).k("Ctrl+K").gap(),
603:                     ],
604:                     anchors[0],
605:                 )
606:             } else {
607:                 (menus.get(mi_idx - 1).map(|m| m.1.clone()).unwrap_or_default(), anchors.get(mi_idx).copied().unwrap_or(anchors[0]))
