                let st = egui::Stroke::new(1.35, k);
                match *n {
                    "close" => {
                        p.line_segment([ctr + vec2(-2.8, -2.8), ctr + vec2(2.8, 2.8)], st);
                        p.line_segment([ctr + vec2(2.8, -2.8), ctr + vec2(-2.8, 2.8)], st);
