            p.text(pos2(card.left() + 136.0, y + 10.0), Align2::LEFT_CENTER, self.fit(&p, &v, &f_semi(T_BODY), card.width() - 170.0), f_semi(T_BODY), th.ink1);
            y += 28.0;
        }
